UPDATE public.location_cards SET biome_config = biome_config || jsonb_build_object('WARDROBE_WOMEN', '["a striking shieldmaiden in fitted dark-leather armor that flatters the figure, a cropped fur-trimmed half-cape swept off one shoulder, sleek styled warrior braids, silver arm-rings, a round shield slung at the back", "a fierce warrior woman in a form-fitting studded-leather bodice over a slim tunic, a short fur collar, a bold streak of blue woad along one cheekbone, hair in a braided undercut, a seax at the hip", "battle-worn fitted leather-and-iron lamellar over a lean tunic, a fur mantle swept off one shoulder, hair swept back in tight side-braids, silver arm-rings, a bearded axe held with easy confidence", "a lean raider in a fitted riveted-leather jerkin and weathered bracers, a short fur-trimmed cloak, long braids threaded with iron rings, a seax and coiled rope", "a commanding jarl in a sharp fitted dark tunic under a trim fur-collared cloak clasped with a silver wolf brooch, gold arm-rings, a sheathed longsword at the hip", "a bold Norse warrior in sleek burnished-leather armor with a wolf-fang pendant and a cropped fur mantle, styled braids, blue woad war-lines, a great axe resting over one shoulder", "a shieldmaiden in a fitted leather cuirass over a deep-crimson slim tunic, tall laced boots, hair in an intricate crown braid, a slung shield and a spear planted at her side", "sleek seafarer leathers with a trim fur-lined storm cloak, salt-worn bracers, braided hair whipping in the wind, a hunting bow slung across the back"]'::jsonb)
  WHERE name = 'viking longhouse';
